{"command":"cat > hx.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <ctype.h>
#include <unistd.h>
#include <limits.h>
#include <math.h>
#include <libgen.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846264338327950288
#endif

typedef struct {
    size_t cols;
    size_t len;
    char format;
    int color;      // -1 auto, 0 off, 1 on
    char array;
    bool has_array;
    size_t func;
    bool has_func;
    size_t places;
    bool has_places;
    int prefix;
    char *input;

    bool seen_cols, seen_len, seen_format, seen_color, seen_array, seen_func, seen_places, seen_prefix;
} Options;

static const char *progname(const char *argv0) {
    const char *s = strrchr(argv0, '/');
    return s ? s + 1 : argv0;
}

static void print_help(const char *prog) {
    printf("Futuristic take on hexdump, made in Rust.\n\n\n");
    printf("Usage: %s [OPTIONS] [INPUTFILE]\n\n", prog);
    printf("Arguments:\n");
    printf("  [INPUTFILE]  Pass file path as an argument, or input data may be passed via stdin\n\n");
    printf("Options:\n");
    printf("  -c, --cols <columns>        Set column length\n");
    printf("  -l, --len <len>             Set <len> bytes to read\n");
    printf("  -f, --format <format>       Set format of octet: Octal (o), LowerHex (x), UpperHex (X), Binary (b) [possible values: o, x, X, b]\n");
    printf("  -t, --color <color>         Set color tint terminal output. 0 to disable, 1 to enable [possible values: 0, 1]\n");
    printf("  -a, --array <array_format>  Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f) [possible values: r, c, g, p, k, j, s, f]\n");
    printf("  -u, --func <func_length>    Set function wave length\n");
    printf("  -p, --places <func_places>  Set function wave output decimal places\n");
    printf("  -r, --prefix <prefix>       Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable [possible values: 0, 1]\n");
    printf("  -h, --help                  Print help\n");
    printf("  -V, --version               Print version\n");
}

static void print_version(void) {
    printf("hx 0.7.0\n");
}

static int usage_error(const char *prog, const char *msg, const char *usage_suffix, bool blank_tip) {
    (void)blank_tip;
    fprintf(stderr, "%s\n\n", msg);
    if (usage_suffix)
        fprintf(stderr, "Usage: %s %s\n\n", prog, usage_suffix);
    else
        fprintf(stderr, "Usage: %s [OPTIONS] [INPUTFILE]\n\n", prog);
    fprintf(stderr, "For more information, try '--help'.\n");
    return 2;
}

static int unexpected_arg(const char *prog, const char *arg, const char *similar, const char *usage_suffix) {
    fprintf(stderr, "error: unexpected argument '%s' found\n\n", arg);
    if (similar) {
        fprintf(stderr, "  tip: a similar argument exists: '%s'\n\n", similar);
    } else if (arg[0] == '-') {
        fprintf(stderr, "  tip: to pass '%s' as a value, use '-- %s'\n\n", arg, arg);
    }
    if (usage_suffix)
        fprintf(stderr, "Usage: %s %s\n\n", prog, usage_suffix);
    else
        fprintf(stderr, "Usage: %s [OPTIONS] [INPUTFILE]\n\n", prog);
    fprintf(stderr, "For more information, try '--help'.\n");
    return 2;
}

static int duplicate_error(const char *prog, const char *canonical) {
    char buf[256];
    snprintf(buf, sizeof(buf), "error: the argument '%s' cannot be used multiple times", canonical);
    return usage_error(prog, buf, NULL, false);
}

static int missing_value_error(const char *opt, const char *possible) {
    fprintf(stderr, "error: a value is required for '%s' but none was supplied\n", opt);
    if (possible) fprintf(stderr, "  [possible values: %s]\n", possible);
    fprintf(stderr, "\nFor more information, try '--help'.\n");
    return 2;
}

static int invalid_value_error(const char *opt, const char *value, const char *possible) {
    fprintf(stderr, "error: invalid value '%s' for '%s'\n", value, opt);
    if (possible) fprintf(stderr, "  [possible values: %s]\n", possible);
    fprintf(stderr, "\nFor more information, try '--help'.\n");
    return 2;
}

static int parse_int_error(const char *prefix, const char *kind, const char *text) {
    fprintf(stderr, "%s expected. ParseIntError { kind: %s }\n", prefix, kind);
    fprintf(stderr, "error: %s\n", text);
    return 1;
}

static int parse_usize_value(const char *s, size_t *out, const char *errprefix) {
    if (s == NULL || *s == '\0') {
        return parse_int_error(errprefix, "Empty", "cannot parse integer from empty string");
    }
    unsigned long long val = 0;
    for (const unsigned char *p = (const unsigned char *)s; *p; ++p) {
        if (!isdigit(*p)) {
            return parse_int_error(errprefix, "InvalidDigit", "invalid digit found in string");
        }
        unsigned digit = (unsigned)(*p - '0');
        if (val > (ULLONG_MAX - digit) / 10ULL) {
            return parse_int_error(errprefix, "PosOverflow", "number too large to fit in target type");
        }
        val = val * 10ULL + digit;
    }
    if (val > (unsigned long long)SIZE_MAX) {
        return parse_int_error(errprefix, "PosOverflow", "number too large to fit in target type");
    }
    *out = (size_t)val;
    return 0;
}

static bool starts_with(const char *s, const char *p) {
    return strncmp(s, p, strlen(p)) == 0;
}

static const char *similar_for(const char *arg, const char **usage_suffix) {
    *usage_suffix = NULL;
    if (starts_with(arg, "--col")) { *usage_suffix = "--cols <columns> [INPUTFILE]"; return "--cols"; }
    if (starts_with(arg, "--for")) { *usage_suffix = "--format <format> [INPUTFILE]"; return "--format"; }
    if (starts_with(arg, "--arr")) { *usage_suffix = "--array <array_format> [INPUTFILE]"; return "--array"; }
    if (starts_with(arg, "--pref")) { *usage_suffix = "--prefix <prefix> [INPUTFILE]"; return "--prefix"; }
    if (starts_with(arg, "--pla")) { *usage_suffix = "--places <func_places> [INPUTFILE]"; return "--places"; }
    if (starts_with(arg, "--func")) { *usage_suffix = "--func <func_length> [INPUTFILE]"; return "--func"; }
    if (starts_with(arg, "--len")) { *usage_suffix = "--len <len> [INPUTFILE]"; return "--len"; }
    if (starts_with(arg, "--color") || starts_with(arg, "--colo")) { *usage_suffix = "--color <color> [INPUTFILE]"; return "--color"; }
    return NULL;
}

typedef enum { OPT_NONE, OPT_COLS, OPT_LEN, OPT_FORMAT, OPT_COLOR, OPT_ARRAY, OPT_FUNC, OPT_PLACES, OPT_PREFIX } OptKind;

static const char *long_canonical(OptKind k) {
    switch (k) {
        case OPT_COLS: return "--cols <columns>";
        case OPT_LEN: return "--len <len>";
        case OPT_FORMAT: return "--format <format>";
        case OPT_COLOR: return "--color <color>";
        case OPT_ARRAY: return "--array <array_format>";
        case OPT_FUNC: return "--func <func_length>";
        case OPT_PLACES: return "--places <func_places>";
        case OPT_PREFIX: return "--prefix <prefix>";
        default: return "";
    }
}

static const char *num_err_prefix(OptKind k) {
    switch (k) {
        case OPT_COLS: return "-c, --cols <integer>";
        case OPT_LEN: return "-l, --len <integer>";
        case OPT_FUNC: return "-u, --func <integer>";
        case OPT_PLACES: return "-p, --places <integer>";
        default: return "";
    }
}

static bool *seen_ptr(Options *o, OptKind k) {
    switch (k) {
        case OPT_COLS: return &o->seen_cols;
        case OPT_LEN: return &o->seen_len;
        case OPT_FORMAT: return &o->seen_format;
        case OPT_COLOR: return &o->seen_color;
        case OPT_ARRAY: return &o->seen_array;
        case OPT_FUNC: return &o->seen_func;
        case OPT_PLACES: return &o->seen_places;
        case OPT_PREFIX: return &o->seen_prefix;
        default: return NULL;
    }
}

static int set_option_value(const char *prog, Options *o, OptKind k, const char *value, bool empty_from_equals) {
    bool *seen = seen_ptr(o, k);
    if (seen && *seen) return duplicate_error(prog, long_canonical(k));
    if (seen) *seen = true;

    // Clap reports empty enum/bool values as missing-value, but custom numeric parsers see Empty.
    if (value == NULL || (empty_from_equals && *value == '\0' && !(k == OPT_COLS || k == OPT_LEN || k == OPT_FUNC || k == OPT_PLACES))) {
        const char *poss = NULL;
        if (k == OPT_FORMAT) poss = "o, x, X, b";
        else if (k == OPT_COLOR || k == OPT_PREFIX) poss = "0, 1";
        else if (k == OPT_ARRAY) poss = "r, c, g, p, k, j, s, f";
        return missing_value_error(long_canonical(k), poss);
    }

    size_t n = 0;
    int rc;
    switch (k) {
        case OPT_COLS:
            rc = parse_usize_value(value, &n, num_err_prefix(k)); if (rc) return rc; o->cols = n; break;
        case OPT_LEN:
            rc = parse_usize_value(value, &n, num_err_prefix(k)); if (rc) return rc; o->len = n; break;
        case OPT_FUNC:
            rc = parse_usize_value(value, &n, num_err_prefix(k)); if (rc) return rc; o->func = n; o->has_func = true; break;
        case OPT_PLACES:
            rc = parse_usize_value(value, &n, num_err_prefix(k)); if (rc) return rc; o->places = n; o->has_places = true; break;
        case OPT_FORMAT:
            if (strcmp(value, "o") && strcmp(value, "x") && strcmp(value, "X") && strcmp(value, "b"))
                return invalid_value_error(long_canonical(k), value, "o, x, X, b");
            o->format = value[0]; break;
        case OPT_COLOR:
            if (strcmp(value, "0") && strcmp(value, "1"))
                return invalid_value_error(long_canonical(k), value, "0, 1");
            o->color = value[0] - '0'; break;
        case OPT_PREFIX:
            if (strcmp(value, "0") && strcmp(value, "1"))
                return invalid_value_error(long_canonical(k), value, "0, 1");
            o->prefix = value[0] - '0'; break;
        case OPT_ARRAY:
            if (strlen(value) != 1 || strchr("rcgpkjsf", value[0]) == NULL)
                return invalid_value_error(long_canonical(k), value, "r, c, g, p, k, j, s, f");
            o->array = value[0]; o->has_array = true; break;
        default: break;
    }
    return 0;
}

static OptKind long_kind(const char *name) {
    if (!strcmp(name, "cols")) return OPT_COLS;
    if (!strcmp(name, "len")) return OPT_LEN;
    if (!strcmp(name, "format")) return OPT_FORMAT;
    if (!strcmp(name, "color")) return OPT_COLOR;
    if (!strcmp(name, "array")) return OPT_ARRAY;
    if (!strcmp(name, "func")) return OPT_FUNC;
    if (!strcmp(name, "places")) return OPT_PLACES;
    if (!strcmp(name, "prefix")) return OPT_PREFIX;
    return OPT_NONE;
}

static OptKind short_kind(char c) {
    switch (c) {
        case 'c': return OPT_COLS;
        case 'l': return OPT_LEN;
        case 'f': return OPT_FORMAT;
        case 't': return OPT_COLOR;
        case 'a': return OPT_ARRAY;
        case 'u': return OPT_FUNC;
        case 'p': return OPT_PLACES;
        case 'r': return OPT_PREFIX;
        default: return OPT_NONE;
    }
}

static int parse_args(int argc, char **argv, Options *o) {
    const char *prog = progname(argv[0]);
    memset(o, 0, sizeof(*o));
    o->cols = 10;
    o->len = 0;
    o->format = 'x';
    o->color = -1;
    o->places = 4;
    o->prefix = 1;

    bool after_double_dash = false;
    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];
        if (!after_double_dash && strcmp(arg, "--") == 0) {
            after_double_dash = true;
            continue;
        }
        if (!after_double_dash && arg[0] == '-' && arg[1] != '\0') {
            if (strcmp(arg, "-h") == 0 || strcmp(arg, "--help") == 0) { print_help(prog); exit(0); }
            if (strcmp(arg, "-V") == 0 || strcmp(arg, "--version") == 0) { print_version(); exit(0); }
            if (arg[1] == '-') {
                char *name = arg + 2;
                char *eq = strchr(name, '=');
                char tmp[128];
                const char *val = NULL;
                bool had_eq = false;
                if (eq) {
                    size_t nl = (size_t)(eq - name);
                    if (nl >= sizeof(tmp)) nl = sizeof(tmp) - 1;
                    memcpy(tmp, name, nl); tmp[nl] = '\0';
                    name = tmp;
                    val = eq + 1;
                    had_eq = true;
                }
                OptKind k = long_kind(name);
                if (k == OPT_NONE) {
                    const char *usage_suf = NULL;
                    const char *sim = similar_for(arg, &usage_suf);
                    return unexpected_arg(prog, arg, sim, usage_suf);
                }
                if (!had_eq) {
                    if (i + 1 >= argc) return missing_value_error(long_canonical(k), (k==OPT_FORMAT?"o, x, X, b":(k==OPT_COLOR||k==OPT_PREFIX?"0, 1":(k==OPT_ARRAY?"r, c, g, p, k, j, s, f":NULL))));
                    if (argv[i+1][0] == '-' && argv[i+1][1] != '\0') {
                        // Match clap's treatment of hyphenated would-be values as separate unexpected args.
                        return unexpected_arg(prog, argv[i+1], NULL, NULL);
                    }
                    val = argv[++i];
                }
                int rc = set_option_value(prog, o, k, val, had_eq);
                if (rc) return rc;
            } else {
                char c = arg[1];
                if (arg[2] == '\0' && (c == 'h' || c == 'V')) {
                    if (c == 'h') { print_help(prog); exit(0); }
                    print_version(); exit(0);
                }
                OptKind k = short_kind(c);
                if (k == OPT_NONE) return unexpected_arg(prog, arg, NULL, NULL);
                const char *val = NULL;
                bool inline_val = false;
                if (arg[2] != '\0') {
                    val = arg + 2;
                    inline_val = true;
                } else {
                    if (i + 1 >= argc) return missing_value_error(long_canonical(k), (k==OPT_FORMAT?"o, x, X, b":(k==OPT_COLOR||k==OPT_PREFIX?"0, 1":(k==OPT_ARRAY?"r, c, g, p, k, j, s, f":NULL))));
                    if (argv[i+1][0] == '-' && argv[i+1][1] != '\0') {
                        return unexpected_arg(prog, argv[i+1], NULL, NULL);
                    }
                    val = argv[++i];
                }
                (void)inline_val;
                int rc = set_option_value(prog, o, k, val, false);
                if (rc) return rc;
            }
        } else {
            if (o->input == NULL) {
                o->input = arg;
            } else {
                if (strcmp(arg, "--") == 0) {
                    // clap accepts a trailing -- after the positional in observed behavior
                    continue;
                }
                return unexpected_arg(prog, arg, NULL, NULL);
            }
        }
    }
    return 0;
}

static int read_all(FILE *fp, size_t limit, unsigned char **out, size_t *outlen) {
    size_t cap = 8192;
    if (limit > 0 && limit < cap) cap = limit;
    if (cap == 0) cap = 1;
    unsigned char *buf = (unsigned char *)malloc(cap);
    if (!buf) return -1;
    size_t len = 0;
    for (;;) {
        if (limit > 0 && len >= limit) break;
        if (len == cap) {
            size_t newcap = cap * 2;
            if (newcap < cap) { free(buf); errno = ENOMEM; return -1; }
            if (limit > 0 && newcap > limit) newcap = limit;
            if (newcap == cap) break;
            unsigned char *nb = (unsigned char *)realloc(buf, newcap);
            if (!nb) { free(buf); return -1; }
            buf = nb; cap = newcap;
        }
        size_t want = cap - len;
        if (limit > 0 && want > limit - len) want = limit - len;
        if (want == 0) break;
        size_t n = fread(buf + len, 1, want, fp);
        len += n;
        if (n < want) {
            if (ferror(fp)) { free(buf); return -1; }
            break;
        }
    }
    *out = buf;
    *outlen = len;
    return 0;
}

static int read_input(const Options *o, unsigned char **data, size_t *len) {
    FILE *fp = stdin;
    if (o->input) {
        fp = fopen(o->input, "rb");
        if (!fp) {
            fprintf(stderr, "error: %s (os error %d)\n", strerror(errno), errno);
            return 1;
        }
    }
    int rc = read_all(fp, o->len, data, len);
    if (o->input) fclose(fp);
    if (rc != 0) {
        fprintf(stderr, "error: %s (os error %d)\n", strerror(errno), errno);
        return 1;
    }
    return 0;
}

static void format_token(unsigned char b, char fmt, int prefix, char *buf, size_t bufsz) {
    switch (fmt) {
        case 'X':
            if (prefix) snprintf(buf, bufsz, "0x%02X", b); else snprintf(buf, bufsz, "%02X", b);
            break;
        case 'o':
            if (prefix) snprintf(buf, bufsz, "0o%04o", b); else snprintf(buf, bufsz, "%04o", b);
            break;
        case 'b': {
            char bits[9];
            for (int i = 7; i >= 0; --i) bits[7-i] = (b & (1u << i)) ? '1' : '0';
            bits[8] = '\0';
            if (prefix) snprintf(buf, bufsz, "0b%s", bits); else snprintf(buf, bufsz, "%s", bits);
            break;
        }
        case 'x':
        default:
            if (prefix) snprintf(buf, bufsz, "0x%02x", b); else snprintf(buf, bufsz, "%02x", b);
            break;
    }
}

static int color_code(unsigned char b) {
    return b == 0 ? 22 : (int)b;
}

static char ascii_char(unsigned char b) {
    if (b >= 0x20 && b <= 0x7e) return (char)b;
    return '.';
}

static void print_colored(const char *s, unsigned char b) {
    printf("\033[38;5;%dm%s\033[0m", color_code(b), s);
}

static void dump_output(const unsigned char *data, size_t len, const Options *o) {
    bool use_color = false;
    if (o->color == 1) use_color = true;
    else if (o->color == 0) use_color = false;
    else use_color = (isatty(STDOUT_FILENO) && getenv("NO_COLOR") == NULL);

    size_t step = o->cols == 0 ? 1 : o->cols;
    for (size_t off = 0; off <= len; ) {
        size_t remain = len - off;
        size_t n = remain < step ? remain : step;
        printf("0x%06zx: ", off);
        for (size_t i = 0; i < n; ++i) {
            char tok[32];
            format_token(data[off + i], o->format, o->prefix, tok, sizeof(tok));
            if (use_color) print_colored(tok, data[off + i]); else fputs(tok, stdout);
            putchar(' ');
        }
        for (size_t i = n; i < o->cols; ++i) {
            fputs("     ", stdout);
        }
        for (size_t i = 0; i < n; ++i) {
            char ch[2] = { ascii_char(data[off + i]), '\0' };
            if (use_color) print_colored(ch, data[off + i]); else fputs(ch, stdout);
        }
        putchar('\n');
        if (off == len) break;
        if (step > len - off) break; // should only happen after a partial final line
        off += step;
    }
    printf("   bytes: %zu\n", len);
}

static void print_array_body(const unsigned char *data, size_t len, const Options *o, char lang) {
    size_t step = o->cols == 0 ? 1 : o->cols;
    for (size_t off = 0; off <= len; ) {
        size_t remain = len - off;
        size_t n = remain < step ? remain : step;
        fputs("    ", stdout);
        for (size_t i = 0; i < n; ++i) {
            unsigned char b = data[off + i];
            bool is_last = (off + i + 1 == len);
            if (lang == 'f') {
                printf("0x%02xuy", b);
                if (!is_last) fputs("; ", stdout);
            } else if (lang == 'g') {
                printf("0x%02x, ", b);
            } else {
                printf("0x%02x", b);
                if (!is_last) fputs(", ", stdout);
            }
        }
        putchar('\n');
        if (off == len) break;
        if (step > len - off) break;
        off += step;
    }
}

static void array_output(const unsigned char *data, size_t len, const Options *o) {
    char a = o->array;
    switch (a) {
        case 'r': printf("let ARRAY: [u8; %zu] = [\n", len); break;
        case 'c': printf("unsigned char ARRAY[%zu] = {\n", len); break;
        case 'g': printf("a := [%zu]byte{\n", len); break;
        case 'p': printf("a = [\n"); break;
        case 'k': printf("val a = byteArrayOf(\n"); break;
        case 'j': printf("byte[] a = new byte[]{\n"); break;
        case 's': printf("let a: [UInt8] = [\n"); break;
        case 'f': printf("let a = [|\n"); break;
        default: break;
    }
    print_array_body(data, len, o, a);
    switch (a) {
        case 'r':
        case 'c':
        case 'j': printf("];\n"); break;
        case 'g': printf("}\n"); break;
        case 'p':
        case 's': printf("]\n"); break;
        case 'k': printf(")\n"); break;
        case 'f': printf("|]\n"); break;
        default: break;
    }
}

static void func_output(const Options *o) {
    size_t n = o->func;
    size_t places = o->places;
    char fmt[32];
    if (places > 1000) places = 1000; // avoid pathological format strings; normal parser accepts it but practical output is finite in tests
    snprintf(fmt, sizeof(fmt), "%%.%zuf,", places);
    for (size_t i = 0; i < n; ++i) {
        double v = sin(((double)i * M_PI) / (2.0 * (double)n));
        printf(fmt, v);
        if (i % 10 == 9) putchar('\n');
    }
    putchar('\n');
}

int main(int argc, char **argv) {
    Options opt;
    int rc = parse_args(argc, argv, &opt);
    if (rc) return rc;

    if (opt.has_func) {
        func_output(&opt);
        return 0;
    }

    unsigned char *data = NULL;
    size_t len = 0;
    rc = read_input(&opt, &data, &len);
    if (rc) return rc;

    if (opt.has_array) array_output(data, len, &opt);
    else dump_output(data, len, &opt);
    free(data);
    return 0;
}
EOF
cat > compile.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")"
rm -f executable
gcc -std=c99 -O2 -Wall -Wextra -pedantic hx.c -lm -o executable
EOF
chmod +x compile.sh
cat > .gitignore <<'EOF'
/executable
*.o
/tmp_out*
EOF
ls -l hx.c compile.sh .gitignore"}

actions.command:
cat > hx.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <ctype.h>
#include <unistd.h>
#include <limits.h>
#include <math.h>
#include <libgen.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846264338327950288
#endif

typedef struct {
    size_t cols;
    size_t len;
    char format;
    int color;      // -1 auto, 0 off, 1 on
    char array;
    bool has_array;
    size_t func;
    bool has_func;
    size_t places;
    bool has_places;
    int prefix;
    char *input;

    bool seen_cols, seen_len, seen_format, seen_color, seen_array, seen_func, seen_places, seen_prefix;
} Options;

static const char *progname(const char *argv0) {
    const char *s = strrchr(argv0, '/');
    return s ? s + 1 : argv0;
}

static void print_help(const char *prog) {
    printf("Futuristic take on hexdump, made in Rust.\n\n\n");
    printf("Usage: %s [OPTIONS] [INPUTFILE]\n\n", prog);
    printf("Arguments:\n");
    printf("  [INPUTFILE]  Pass file path as an argument, or input data may be passed via stdin\n\n");
    printf("Options:\n");
    printf("  -c, --cols <columns>        Set column length\n");
    printf("  -l, --len <len>             Set <len> bytes to read\n");
    printf("  -f, --format <format>       Set format of octet: Octal (o), LowerHex (x), UpperHex (X), Binary (b) [possible values: o, x, X, b]\n");
    printf("  -t, --color <color>         Set color tint terminal output. 0 to disable, 1 to enable [possible values: 0, 1]\n");
    printf("  -a, --array <array_format>  Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f) [possible values: r, c, g, p, k, j, s, f]\n");
    printf("  -u, --func <func_length>    Set function wave length\n");
    printf("  -p, --places <func_places>  Set function wave output decimal places\n");
    printf("  -r, --prefix <prefix>       Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable [possible values: 0, 1]\n");
    printf("  -h, --help                  Print help\n");
    printf("  -V, --version               Print version\n");
}

static void print_version(void) {
    printf("hx 0.7.0\n");
}

static int usage_error(const char *prog, const char *msg, const char *usage_suffix, bool blank_tip) {
    (void)blank_tip;
    fprintf(stderr, "%s\n\n", msg);
    if (usage_suffix)
        fprintf(stderr, "Usage: %s %s\n\n", prog, usage_suffix);
    else
        fprintf(stderr, "Usage: %s [OPTIONS] [INPUTFILE]\n\n", prog);
    fprintf(stderr, "For more information, try '--help'.\n");
    return 2;
}

static int unexpected_arg(const char *prog, const char *arg, const char *similar, const char *usage_suffix) {
    fprintf(stderr, "error: unexpected argument '%s' found\n\n", arg);
    if (similar) {
        fprintf(stderr, "  tip: a similar argument exists: '%s'\n\n", similar);
    } else if (arg[0] == '-') {
        fprintf(stderr, "  tip: to pass '%s' as a value, use '-- %s'\n\n", arg, arg);
    }
    if (usage_suffix)
        fprintf(stderr, "Usage: %s %s\n\n", prog, usage_suffix);
    else
        fprintf(stderr, "Usage: %s [OPTIONS] [INPUTFILE]\n\n", prog);
    fprintf(stderr, "For more information, try '--help'.\n");
    return 2;
}

static int duplicate_error(const char *prog, const char *canonical) {
    char buf[256];
    snprintf(buf, sizeof(buf), "error: the argument '%s' cannot be used multiple times", canonical);
    return usage_error(prog, buf, NULL, false);
}

static int missing_value_error(const char *opt, const char *possible) {
    fprintf(stderr, "error: a value is required for '%s' but none was supplied\n", opt);
    if (possible) fprintf(stderr, "  [possible values: %s]\n", possible);
    fprintf(stderr, "\nFor more information, try '--help'.\n");
    return 2;
}

static int invalid_value_error(const char *opt, const char *value, const char *possible) {
    fprintf(stderr, "error: invalid value '%s' for '%s'\n", value, opt);
    if (possible) fprintf(stderr, "  [possible values: %s]\n", possible);
    fprintf(stderr, "\nFor more information, try '--help'.\n");
    return 2;
}

static int parse_int_error(const char *prefix, const char *kind, const char *text) {
    fprintf(stderr, "%s expected. ParseIntError { kind: %s }\n", prefix, kind);
    fprintf(stderr, "error: %s\n", text);
    return 1;
}

static int parse_usize_value(const char *s, size_t *out, const char *errprefix) {
    if (s == NULL || *s == '\0') {
        return parse_int_error(errprefix, "Empty", "cannot parse integer from empty string");
    }
    unsigned long long val = 0;
    for (const unsigned char *p = (const unsigned char *)s; *p; ++p) {
        if (!isdigit(*p)) {
            return parse_int_error(errprefix, "InvalidDigit", "invalid digit found in string");
        }
        unsigned digit = (unsigned)(*p - '0');
        if (val > (ULLONG_MAX - digit) / 10ULL) {
            return parse_int_error(errprefix, "PosOverflow", "number too large to fit in target type");
        }
        val = val * 10ULL + digit;
    }
    if (val > (unsigned long long)SIZE_MAX) {
        return parse_int_error(errprefix, "PosOverflow", "number too large to fit in target type");
    }
    *out = (size_t)val;
    return 0;
}

static bool starts_with(const char *s, const char *p) {
    return strncmp(s, p, strlen(p)) == 0;
}

static const char *similar_for(const char *arg, const char **usage_suffix) {
    *usage_suffix = NULL;
    if (starts_with(arg, "--col")) { *usage_suffix = "--cols <columns> [INPUTFILE]"; return "--cols"; }
    if (starts_with(arg, "--for")) { *usage_suffix = "--format <format> [INPUTFILE]"; return "--format"; }
    if (starts_with(arg, "--arr")) { *usage_suffix = "--array <array_format> [INPUTFILE]"; return "--array"; }
    if (starts_with(arg, "--pref")) { *usage_suffix = "--prefix <prefix> [INPUTFILE]"; return "--prefix"; }
    if (starts_with(arg, "--pla")) { *usage_suffix = "--places <func_places> [INPUTFILE]"; return "--places"; }
    if (starts_with(arg, "--func")) { *usage_suffix = "--func <func_length> [INPUTFILE]"; return "--func"; }
    if (starts_with(arg, "--len")) { *usage_suffix = "--len <len> [INPUTFILE]"; return "--len"; }
    if (starts_with(arg, "--color") || starts_with(arg, "--colo")) { *usage_suffix = "--color <color> [INPUTFILE]"; return "--color"; }
    return NULL;
}

typedef enum { OPT_NONE, OPT_COLS, OPT_LEN, OPT_FORMAT, OPT_COLOR, OPT_ARRAY, OPT_FUNC, OPT_PLACES, OPT_PREFIX } OptKind;

static const char *long_canonical(OptKind k) {
    switch (k) {
        case OPT_COLS: return "--cols <columns>";
        case OPT_LEN: return "--len <len>";
        case OPT_FORMAT: return "--format <format>";
        case OPT_COLOR: return "--color <color>";
        case OPT_ARRAY: return "--array <array_format>";
        case OPT_FUNC: return "--func <func_length>";
        case OPT_PLACES: return "--places <func_places>";
        case OPT_PREFIX: return "--prefix <prefix>";
        default: return "";
    }
}

static const char *num_err_prefix(OptKind k) {
    switch (k) {
        case OPT_COLS: return "-c, --cols <integer>";
        case OPT_LEN: return "-l, --len <integer>";
        case OPT_FUNC: return "-u, --func <integer>";
        case OPT_PLACES: return "-p, --places <integer>";
        default: return "";
    }
}

static bool *seen_ptr(Options *o, OptKind k) {
    switch (k) {
        case OPT_COLS: return &o->seen_cols;
        case OPT_LEN: return &o->seen_len;
        case OPT_FORMAT: return &o->seen_format;
        case OPT_COLOR: return &o->seen_color;
        case OPT_ARRAY: return &o->seen_array;
        case OPT_FUNC: return &o->seen_func;
        case OPT_PLACES: return &o->seen_places;
        case OPT_PREFIX: return &o->seen_prefix;
        default: return NULL;
    }
}

static int set_option_value(const char *prog, Options *o, OptKind k, const char *value, bool empty_from_equals) {
    bool *seen = seen_ptr(o, k);
    if (seen && *seen) return duplicate_error(prog, long_canonical(k));
    if (seen) *seen = true;

    // Clap reports empty enum/bool values as missing-value, but custom numeric parsers see Empty.
    if (value == NULL || (empty_from_equals && *value == '\0' && !(k == OPT_COLS || k == OPT_LEN || k == OPT_FUNC || k == OPT_PLACES))) {
        const char *poss = NULL;
        if (k == OPT_FORMAT) poss = "o, x, X, b";
        else if (k == OPT_COLOR || k == OPT_PREFIX) poss = "0, 1";
        else if (k == OPT_ARRAY) poss = "r, c, g, p, k, j, s, f";
        return missing_value_error(long_canonical(k), poss);
    }

    size_t n = 0;
    int rc;
    switch (k) {
        case OPT_COLS:
            rc = parse_usize_value(value, &n, num_err_prefix(k)); if (rc) return rc; o->cols = n; break;
        case OPT_LEN:
            rc = parse_usize_value(value, &n, num_err_prefix(k)); if (rc) return rc; o->len = n; break;
        case OPT_FUNC:
            rc = parse_usize_value(value, &n, num_err_prefix(k)); if (rc) return rc; o->func = n; o->has_func = true; break;
        case OPT_PLACES:
            rc = parse_usize_value(value, &n, num_err_prefix(k)); if (rc) return rc; o->places = n; o->has_places = true; break;
        case OPT_FORMAT:
            if (strcmp(value, "o") && strcmp(value, "x") && strcmp(value, "X") && strcmp(value, "b"))
                return invalid_value_error(long_canonical(k), value, "o, x, X, b");
            o->format = value[0]; break;
        case OPT_COLOR:
            if (strcmp(value, "0") && strcmp(value, "1"))
                return invalid_value_error(long_canonical(k), value, "0, 1");
            o->color = value[0] - '0'; break;
        case OPT_PREFIX:
            if (strcmp(value, "0") && strcmp(value, "1"))
                return invalid_value_error(long_canonical(k), value, "0, 1");
            o->prefix = value[0] - '0'; break;
        case OPT_ARRAY:
            if (strlen(value) != 1 || strchr("rcgpkjsf", value[0]) == NULL)
                return invalid_value_error(long_canonical(k), value, "r, c, g, p, k, j, s, f");
            o->array = value[0]; o->has_array = true; break;
        default: break;
    }
    return 0;
}

static OptKind long_kind(const char *name) {
    if (!strcmp(name, "cols")) return OPT_COLS;
    if (!strcmp(name, "len")) return OPT_LEN;
    if (!strcmp(name, "format")) return OPT_FORMAT;
    if (!strcmp(name, "color")) return OPT_COLOR;
    if (!strcmp(name, "array")) return OPT_ARRAY;
    if (!strcmp(name, "func")) return OPT_FUNC;
    if (!strcmp(name, "places")) return OPT_PLACES;
    if (!strcmp(name, "prefix")) return OPT_PREFIX;
    return OPT_NONE;
}

static OptKind short_kind(char c) {
    switch (c) {
        case 'c': return OPT_COLS;
        case 'l': return OPT_LEN;
        case 'f': return OPT_FORMAT;
        case 't': return OPT_COLOR;
        case 'a': return OPT_ARRAY;
        case 'u': return OPT_FUNC;
        case 'p': return OPT_PLACES;
        case 'r': return OPT_PREFIX;
        default: return OPT_NONE;
    }
}

static int parse_args(int argc, char **argv, Options *o) {
    const char *prog = progname(argv[0]);
    memset(o, 0, sizeof(*o));
    o->cols = 10;
    o->len = 0;
    o->format = 'x';
    o->color = -1;
    o->places = 4;
    o->prefix = 1;

    bool after_double_dash = false;
    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];
        if (!after_double_dash && strcmp(arg, "--") == 0) {
            after_double_dash = true;
            continue;
        }
        if (!after_double_dash && arg[0] == '-' && arg[1] != '\0') {
            if (strcmp(arg, "-h") == 0 || strcmp(arg, "--help") == 0) { print_help(prog); exit(0); }
            if (strcmp(arg, "-V") == 0 || strcmp(arg, "--version") == 0) { print_version(); exit(0); }
            if (arg[1] == '-') {
                char *name = arg + 2;
                char *eq = strchr(name, '=');
                char tmp[128];
                const char *val = NULL;
                bool had_eq = false;
                if (eq) {
                    size_t nl = (size_t)(eq - name);
                    if (nl >= sizeof(tmp)) nl = sizeof(tmp) - 1;
                    memcpy(tmp, name, nl); tmp[nl] = '\0';
                    name = tmp;
                    val = eq + 1;
                    had_eq = true;
                }
                OptKind k = long_kind(name);
                if (k == OPT_NONE) {
                    const char *usage_suf = NULL;
                    const char *sim = similar_for(arg, &usage_suf);
                    return unexpected_arg(prog, arg, sim, usage_suf);
                }
                if (!had_eq) {
                    if (i + 1 >= argc) return missing_value_error(long_canonical(k), (k==OPT_FORMAT?"o, x, X, b":(k==OPT_COLOR||k==OPT_PREFIX?"0, 1":(k==OPT_ARRAY?"r, c, g, p, k, j, s, f":NULL))));
                    if (argv[i+1][0] == '-' && argv[i+1][1] != '\0') {
                        // Match clap's treatment of hyphenated would-be values as separate unexpected args.
                        return unexpected_arg(prog, argv[i+1], NULL, NULL);
                    }
                    val = argv[++i];
                }
                int rc = set_option_value(prog, o, k, val, had_eq);
                if (rc) return rc;
            } else {
                char c = arg[1];
                if (arg[2] == '\0' && (c == 'h' || c == 'V')) {
                    if (c == 'h') { print_help(prog); exit(0); }
                    print_version(); exit(0);
                }
                OptKind k = short_kind(c);
                if (k == OPT_NONE) return unexpected_arg(prog, arg, NULL, NULL);
                const char *val = NULL;
                bool inline_val = false;
                if (arg[2] != '\0') {
                    val = arg + 2;
                    inline_val = true;
                } else {
                    if (i + 1 >= argc) return missing_value_error(long_canonical(k), (k==OPT_FORMAT?"o, x, X, b":(k==OPT_COLOR||k==OPT_PREFIX?"0, 1":(k==OPT_ARRAY?"r, c, g, p, k, j, s, f":NULL))));
                    if (argv[i+1][0] == '-' && argv[i+1][1] != '\0') {
                        return unexpected_arg(prog, argv[i+1], NULL, NULL);
                    }
                    val = argv[++i];
                }
                (void)inline_val;
                int rc = set_option_value(prog, o, k, val, false);
                if (rc) return rc;
            }
        } else {
            if (o->input == NULL) {
                o->input = arg;
            } else {
                if (strcmp(arg, "--") == 0) {
                    // clap accepts a trailing -- after the positional in observed behavior
                    continue;
                }
                return unexpected_arg(prog, arg, NULL, NULL);
            }
        }
    }
    return 0;
}

static int read_all(FILE *fp, size_t limit, unsigned char **out, size_t *outlen) {
    size_t cap = 8192;
    if (limit > 0 && limit < cap) cap = limit;
    if (cap == 0) cap = 1;
    unsigned char *buf = (unsigned char *)malloc(cap);
    if (!buf) return -1;
    size_t len = 0;
    for (;;) {
        if (limit > 0 && len >= limit) break;
        if (len == cap) {
            size_t newcap = cap * 2;
            if (newcap < cap) { free(buf); errno = ENOMEM; return -1; }
            if (limit > 0 && newcap > limit) newcap = limit;
            if (newcap == cap) break;
            unsigned char *nb = (unsigned char *)realloc(buf, newcap);
            if (!nb) { free(buf); return -1; }
            buf = nb; cap = newcap;
        }
        size_t want = cap - len;
        if (limit > 0 && want > limit - len) want = limit - len;
        if (want == 0) break;
        size_t n = fread(buf + len, 1, want, fp);
        len += n;
        if (n < want) {
            if (ferror(fp)) { free(buf); return -1; }
            break;
        }
    }
    *out = buf;
    *outlen = len;
    return 0;
}

static int read_input(const Options *o, unsigned char **data, size_t *len) {
    FILE *fp = stdin;
    if (o->input) {
        fp = fopen(o->input, "rb");
        if (!fp) {
            fprintf(stderr, "error: %s (os error %d)\n", strerror(errno), errno);
            return 1;
        }
    }
    int rc = read_all(fp, o->len, data, len);
    if (o->input) fclose(fp);
    if (rc != 0) {
        fprintf(stderr, "error: %s (os error %d)\n", strerror(errno), errno);
        return 1;
    }
    return 0;
}

static void format_token(unsigned char b, char fmt, int prefix, char *buf, size_t bufsz) {
    switch (fmt) {
        case 'X':
            if (prefix) snprintf(buf, bufsz, "0x%02X", b); else snprintf(buf, bufsz, "%02X", b);
            break;
        case 'o':
            if (prefix) snprintf(buf, bufsz, "0o%04o", b); else snprintf(buf, bufsz, "%04o", b);
            break;
        case 'b': {
            char bits[9];
            for (int i = 7; i >= 0; --i) bits[7-i] = (b & (1u << i)) ? '1' : '0';
            bits[8] = '\0';
            if (prefix) snprintf(buf, bufsz, "0b%s", bits); else snprintf(buf, bufsz, "%s", bits);
            break;
        }
        case 'x':
        default:
            if (prefix) snprintf(buf, bufsz, "0x%02x", b); else snprintf(buf, bufsz, "%02x", b);
            break;
    }
}

static int color_code(unsigned char b) {
    return b == 0 ? 22 : (int)b;
}

static char ascii_char(unsigned char b) {
    if (b >= 0x20 && b <= 0x7e) return (char)b;
    return '.';
}

static void print_colored(const char *s, unsigned char b) {
    printf("\033[38;5;%dm%s\033[0m", color_code(b), s);
}

static void dump_output(const unsigned char *data, size_t len, const Options *o) {
    bool use_color = false;
    if (o->color == 1) use_color = true;
    else if (o->color == 0) use_color = false;
    else use_color = (isatty(STDOUT_FILENO) && getenv("NO_COLOR") == NULL);

    size_t step = o->cols == 0 ? 1 : o->cols;
    for (size_t off = 0; off <= len; ) {
        size_t remain = len - off;
        size_t n = remain < step ? remain : step;
        printf("0x%06zx: ", off);
        for (size_t i = 0; i < n; ++i) {
            char tok[32];
            format_token(data[off + i], o->format, o->prefix, tok, sizeof(tok));
            if (use_color) print_colored(tok, data[off + i]); else fputs(tok, stdout);
            putchar(' ');
        }
        for (size_t i = n; i < o->cols; ++i) {
            fputs("     ", stdout);
        }
        for (size_t i = 0; i < n; ++i) {
            char ch[2] = { ascii_char(data[off + i]), '\0' };
            if (use_color) print_colored(ch, data[off + i]); else fputs(ch, stdout);
        }
        putchar('\n');
        if (off == len) break;
        if (step > len - off) break; // should only happen after a partial final line
        off += step;
    }
    printf("   bytes: %zu\n", len);
}

static void print_array_body(const unsigned char *data, size_t len, const Options *o, char lang) {
    size_t step = o->cols == 0 ? 1 : o->cols;
    for (size_t off = 0; off <= len; ) {
        size_t remain = len - off;
        size_t n = remain < step ? remain : step;
        fputs("    ", stdout);
        for (size_t i = 0; i < n; ++i) {
            unsigned char b = data[off + i];
            bool is_last = (off + i + 1 == len);
            if (lang == 'f') {
                printf("0x%02xuy", b);
                if (!is_last) fputs("; ", stdout);
            } else if (lang == 'g') {
                printf("0x%02x, ", b);
            } else {
                printf("0x%02x", b);
                if (!is_last) fputs(", ", stdout);
            }
        }
        putchar('\n');
        if (off == len) break;
        if (step > len - off) break;
        off += step;
    }
}

static void array_output(const unsigned char *data, size_t len, const Options *o) {
    char a = o->array;
    switch (a) {
        case 'r': printf("let ARRAY: [u8; %zu] = [\n", len); break;
        case 'c': printf("unsigned char ARRAY[%zu] = {\n", len); break;
        case 'g': printf("a := [%zu]byte{\n", len); break;
        case 'p': printf("a = [\n"); break;
        case 'k': printf("val a = byteArrayOf(\n"); break;
        case 'j': printf("byte[] a = new byte[]{\n"); break;
        case 's': printf("let a: [UInt8] = [\n"); break;
        case 'f': printf("let a = [|\n"); break;
        default: break;
    }
    print_array_body(data, len, o, a);
    switch (a) {
        case 'r':
        case 'c':
        case 'j': printf("];\n"); break;
        case 'g': printf("}\n"); break;
        case 'p':
        case 's': printf("]\n"); break;
        case 'k': printf(")\n"); break;
        case 'f': printf("|]\n"); break;
        default: break;
    }
}

static void func_output(const Options *o) {
    size_t n = o->func;
    size_t places = o->places;
    char fmt[32];
    if (places > 1000) places = 1000; // avoid pathological format strings; normal parser accepts it but practical output is finite in tests
    snprintf(fmt, sizeof(fmt), "%%.%zuf,", places);
    for (size_t i = 0; i < n; ++i) {
        double v = sin(((double)i * M_PI) / (2.0 * (double)n));
        printf(fmt, v);
        if (i % 10 == 9) putchar('\n');
    }
    putchar('\n');
}

int main(int argc, char **argv) {
    Options opt;
    int rc = parse_args(argc, argv, &opt);
    if (rc) return rc;

    if (opt.has_func) {
        func_output(&opt);
        return 0;
    }

    unsigned char *data = NULL;
    size_t len = 0;
    rc = read_input(&opt, &data, &len);
    if (rc) return rc;

    if (opt.has_array) array_output(data, len, &opt);
    else dump_output(data, len, &opt);
    free(data);
    return 0;
}
EOF
